    /**
     * Validates that the given member exists in the given streams group.
     *
     * @param groupId         The group ID.
     * @param memberId        The member ID.
     * @param committedOffset A specified committed offset corresponding to this shard.
     *
     * @return The StreamsGroupMember for the given member.
     * @throws GroupIdNotFoundException  if the group does not exist.
     * @throws UnknownMemberIdException  if the member does not exist in the group.
     */
    public StreamsGroupMember validateStreamsGroupMember(
        String groupId,
        String memberId,
        long committedOffset
    ) throws GroupIdNotFoundException, UnknownMemberIdException {
        StreamsGroupMember member = streamsGroup(groupId, committedOffset).members().get(memberId, committedOffset);
        if (member == null) {
            throw new UnknownMemberIdException(
                String.format("Member %s is not a member of group %s.", memberId, groupId)
            );
